@push('scripts')<script>function salesmanData(){return{pager:{loading:true,items:[],currentPage:1,perPage:10,total:0,totalPages:1,get visiblePages(){return[]},fetchPage(){return Promise.resolve(false)},setSearch(){},refresh(){return Promise.resolve(false)},goToPage(){},changePerPage(){}},distributors:[],search:'',saving:false,modalOpen:false,deleteModalOpen:false,editId:null,deleteTarget:null,form:{name:'',email:'',phone:'',distributor_id:'',territory:'',target_amount:0},errors:{},async init(){try{this.pager=$store.pager.create({endpoint:'/api/v1/salesman',perPage:10})}catch(e){console.error('Pager create failed:',e);this.pager.loading=false;return}this.fetchDependencies();this.pager.fetchPage()},doSearch(){try{this.pager.setSearch({search:this.search||undefined})}catch(e){this.search=''}},async fetchDependencies(){try{var d=await $store.api.get('/api/v1/distributor',{per_page:200});if(d&&d.status)this.distributors=Array.isArray(d.data)?d.data:(d.data?.data||[])}catch(e){console.error('Failed to load distributors:',e)}},openAddModal(){this.editId=null;this.errors={};this.form={name:'',email:'',phone:'',distributor_id:'',territory:'',target_amount:0};this.modalOpen=true},openEditModal(s){this.editId=s.id;this.errors={};this.form={name:s.name||'',email:s.email||'',phone:s.phone||'',distributor_id:s.distributor_id||'',territory:s.territory||'',target_amount:s.target_amount||0};this.modalOpen=true},confirmDelete(s){this.deleteTarget=s;this.deleteModalOpen=true},closeModal(){this.modalOpen=false;this.editId=null;this.errors={}},async saveItem(){this.errors={};if(!this.form.name){this.errors.name='Name is required';return}this.saving=true;try{this.editId?await $store.api.put('/api/v1/salesman/'+this.editId,this.form):await $store.api.post('/api/v1/salesman',this.form);this.closeModal();$store.toast.success(this.editId?'Salesman updated':'Salesman created');this.pager.refresh()}catch(e){if(e.errors)this.errors=e.errors;else $store.toast.error(e.message||'Save failed')}finally{this.saving=false}},async deleteItem(){if(!this.deleteTarget)return;this.saving=true;try{await $store.api.del('/api/v1/salesman/'+this.deleteTarget.id);this.deleteModalOpen=false;this.deleteTarget=null;$store.toast.success('Salesman deleted');this.pager.refresh()}catch(e){$store.toast.error(e.message||'Delete failed')}finally{this.saving=false}}}}</script>@endpush
